CREATE TABLE fitness_creator_members (creator_id TEXT NOT NULL REFERENCES creators(id), email TEXT NOT NULL, PRIMARY KEY(creator_id,email));
CREATE TABLE fitness_users (id TEXT PRIMARY KEY, creator_id TEXT NOT NULL REFERENCES creators(id), session_hash TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(creator_id,session_hash));
CREATE INDEX fitness_users_by_creator ON fitness_users(creator_id,id);
CREATE TABLE fitness_profiles (creator_id TEXT NOT NULL REFERENCES creators(id), user_id TEXT NOT NULL REFERENCES fitness_users(id), profile_json TEXT NOT NULL, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(creator_id,user_id));
CREATE TABLE fitness_entitlements (creator_id TEXT NOT NULL REFERENCES creators(id), user_id TEXT NOT NULL REFERENCES fitness_users(id), code TEXT NOT NULL, expires_at TEXT, PRIMARY KEY(creator_id,user_id,code));
CREATE TABLE fitness_programs (id TEXT PRIMARY KEY, creator_id TEXT NOT NULL REFERENCES creators(id), title TEXT NOT NULL, summary TEXT NOT NULL, goal TEXT NOT NULL, level TEXT NOT NULL, equipment_json TEXT NOT NULL, limitations TEXT NOT NULL, minutes INTEGER NOT NULL, days_json TEXT NOT NULL, followup_text TEXT NOT NULL DEFAULT '', access_tier TEXT NOT NULL DEFAULT 'free', review_status TEXT NOT NULL DEFAULT 'draft' CHECK(review_status IN ('draft','pending_review','approved','published')), updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX fitness_programs_by_creator ON fitness_programs(creator_id,review_status,updated_at);
CREATE TABLE fitness_program_exercises (id TEXT PRIMARY KEY, creator_id TEXT NOT NULL REFERENCES creators(id), program_id TEXT NOT NULL REFERENCES fitness_programs(id), day_number INTEGER NOT NULL, position INTEGER NOT NULL, exercise_source TEXT NOT NULL, exercise_id TEXT NOT NULL, sets INTEGER NOT NULL, reps TEXT NOT NULL, duration_seconds INTEGER, rest_seconds INTEGER NOT NULL, instructions TEXT NOT NULL, cues TEXT NOT NULL, alternative_exercise_id TEXT, UNIQUE(creator_id,program_id,day_number,position));
CREATE INDEX fitness_exercises_by_program ON fitness_program_exercises(creator_id,program_id,day_number,position);
CREATE TABLE fitness_workouts (creator_id TEXT NOT NULL REFERENCES creators(id), user_id TEXT NOT NULL REFERENCES fitness_users(id), program_id TEXT NOT NULL REFERENCES fitness_programs(id), day_number INTEGER NOT NULL, workout_date TEXT NOT NULL, completed_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, skipped_json TEXT NOT NULL DEFAULT '[]', discomfort_json TEXT NOT NULL DEFAULT '[]', PRIMARY KEY(creator_id,user_id,program_id,day_number,workout_date));
CREATE INDEX fitness_workouts_by_user ON fitness_workouts(creator_id,user_id,completed_at);
CREATE TABLE fitness_reminders (creator_id TEXT NOT NULL REFERENCES creators(id), user_id TEXT NOT NULL REFERENCES fitness_users(id), enabled INTEGER NOT NULL DEFAULT 0, days_json TEXT NOT NULL DEFAULT '[]', hour INTEGER NOT NULL DEFAULT 9, quiet_start INTEGER NOT NULL DEFAULT 22, quiet_end INTEGER NOT NULL DEFAULT 7, followups INTEGER NOT NULL DEFAULT 0, timezone TEXT NOT NULL DEFAULT 'UTC', PRIMARY KEY(creator_id,user_id));
CREATE TABLE fitness_challenges (id TEXT PRIMARY KEY, creator_id TEXT NOT NULL REFERENCES creators(id), program_id TEXT NOT NULL REFERENCES fitness_programs(id), title TEXT NOT NULL, description TEXT NOT NULL, starts_on TEXT NOT NULL, ends_on TEXT NOT NULL, review_status TEXT NOT NULL DEFAULT 'draft' CHECK(review_status IN ('draft','pending_review','approved','published')));
CREATE INDEX fitness_challenges_by_program ON fitness_challenges(creator_id,program_id,review_status);
CREATE TABLE fitness_challenge_members (creator_id TEXT NOT NULL REFERENCES creators(id), challenge_id TEXT NOT NULL REFERENCES fitness_challenges(id), user_id TEXT NOT NULL REFERENCES fitness_users(id), joined_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(creator_id,challenge_id,user_id));
CREATE TABLE fitness_posts (id TEXT PRIMARY KEY, creator_id TEXT NOT NULL REFERENCES creators(id), program_id TEXT NOT NULL REFERENCES fitness_programs(id), user_id TEXT NOT NULL REFERENCES fitness_users(id), body TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'visible' CHECK(status IN ('visible','reported','hidden')), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX fitness_posts_by_program ON fitness_posts(creator_id,program_id,status,created_at);
